package br.com.mathinclui.auth.professor;

import br.com.mathinclui.auth.api.AuthProblemException; import br.com.mathinclui.auth.token.RefreshTokenService; import br.com.mathinclui.professor.domain.Professor; import br.com.mathinclui.professor.repository.ProfessorRepository; import org.junit.jupiter.api.Test; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.*; import java.util.Optional; import static org.assertj.core.api.Assertions.assertThatThrownBy; import static org.mockito.Mockito.*;
class ProfessorAuthServiceTest {
 @Test void shouldRejectDuplicateEmailOnRegistration(){var repository=mock(ProfessorRepository.class);when(repository.existsByEmailIgnoreCase("prof@escola.com")).thenReturn(true);var service=service(repository);assertThatThrownBy(()->service.register(new RegisterProfessorRequest("Professor","prof@escola.com","SenhaForte123"))).isInstanceOf(AuthProblemException.class).hasMessageContaining("cadastrado");}
 @Test void shouldReturnGenericErrorForInactiveProfessorLogin(){var repository=mock(ProfessorRepository.class);var professor=mock(Professor.class);when(professor.isAtivo()).thenReturn(false);when(repository.findByEmailIgnoreCase("prof@escola.com")).thenReturn(Optional.of(professor));var service=service(repository);assertThatThrownBy(()->service.login(new ProfessorLoginRequest("prof@escola.com","SenhaForte123"))).isInstanceOf(AuthProblemException.class).hasMessage("Credenciais inválidas.");}
 @Test void shouldReturnGenericErrorForWrongPassword(){var repository=mock(ProfessorRepository.class);var encoder=mock(PasswordEncoder.class);var professor=mock(Professor.class);when(professor.isAtivo()).thenReturn(true);when(professor.getSenhaHash()).thenReturn("hash");when(repository.findByEmailIgnoreCase("prof@escola.com")).thenReturn(Optional.of(professor));when(encoder.matches("SenhaErrada","hash")).thenReturn(false);var service=new ProfessorAuthService(repository,encoder,mock(RefreshTokenService.class),mock(PasswordResetTokenRepository.class),mock(PasswordResetNotifier.class),Clock.fixed(Instant.parse("2026-10-15T18:00:00Z"),ZoneOffset.UTC),1800);assertThatThrownBy(()->service.login(new ProfessorLoginRequest("prof@escola.com","SenhaErrada"))).isInstanceOf(AuthProblemException.class).hasMessage("Credenciais inválidas.");}
 private ProfessorAuthService service(ProfessorRepository repository){return new ProfessorAuthService(repository,mock(PasswordEncoder.class),mock(RefreshTokenService.class),mock(PasswordResetTokenRepository.class),mock(PasswordResetNotifier.class),Clock.fixed(Instant.parse("2026-10-15T18:00:00Z"),ZoneOffset.UTC),1800);}
}
